    "path": "pilot-workspace/FORMAL-F11-A2/query.json",
    "content": "{\n  \"window\": {\n    \"start\": 100,\n    \"end\": 200\n  },\n  \"filter\": \"level == \\\"info\\\"\",\n  \"limit\": null\n}\n"
