    "path": "pilot-workspace/FORMAL-F11-B1/query.json",
    "content": "{\n  \"window\": {\n    \"start\": 0,\n    \"end\": 1000\n  },\n  \"filter\": \"service == \\\"api\\\" OR level == \\\"error\\\" AND NOT value == 5\",\n  \"limit\": null\n}\n"
